# Generated by packaging/homebrew/generate.sh in https://github.com/theromis/Froxel; edit it there.
# The Linux build; on macOS install the cask instead.
class Froxel < Formula
  desc "Voxel editor with a path tracer and an MCP server"
  homepage "https://github.com/theromis/Froxel"
  version "0.3.4"
  license "MIT"

  livecheck do
    url :stable
    strategy :github_latest
  end

  depends_on :linux

  on_linux do
    on_intel do
      url "https://github.com/theromis/Froxel/releases/download/v#{version}/froxel-#{version}-linux-x86_64.tar.gz"
      sha256 "92db92461c2d0317572354b0a31e033ddd8a5a7d4f2a2e86c8cfb0d820f14814"
    end
    on_arm do
      url "https://github.com/theromis/Froxel/releases/download/v#{version}/froxel-#{version}-linux-aarch64.tar.gz"
      sha256 "27d52aa4fec281a1dd771603b12f74d5553beb7e668febf1bbe0c827444bbad0"
    end
  end

  def install
    bin.install "froxel"
    share.install "froxel.desktop" => "applications/froxel.desktop"
    (share/"metainfo").install "com.lonje.Froxel.metainfo.xml"
    Dir["icons/*.png"].each do |png|
      (share/"icons/hicolor"/File.basename(png, ".png")/"apps").install png => "froxel.png"
    end
  end

  def caveats
    <<~EOS
      Froxel draws with Vulkan, so it needs your distribution's Vulkan loader
      and GPU driver (for example libvulkan1 and mesa-vulkan-drivers).
    EOS
  end

  test do
    assert_match "usage: froxel", shell_output("#{bin}/froxel --help")
  end
end
